"""The add-on license list: what an add-on install brings, and the licenses we must not ship."""

from __future__ import annotations

from pathlib import Path

import pytest

from tools.build import addon_licenses

#: A lock in pip-compile's shape: a header, pins, and ``# via`` in both of its forms.
_LOCK = """\
#
# This file is autogenerated by pip-compile with Python 3.14
# by the following command:
#
#    bazel run //:requirements_addons.update
#
annotated-types==0.8.0
    # via pydantic
langchain-core==1.8.1
    # via teachers-teammate (pyproject.toml)
numpy==2.5.5
    # via
    #   langchain-core
    #   spacy
pydantic==2.14.3
    # via
    #   langchain-core
    #   spacy
pyside6-essentials==6.11.0
    # via teachers-teammate (pyproject.toml)
spacy==3.8.18
    # via teachers-teammate (pyproject.toml)
typer==0.21.0
    # via spacy
"""


def test_closure_follows_the_via_comments_from_the_addons_own_packages() -> None:
    """
    Given  a lock that resolves the whole project, with pip-compile's ``# via`` comments
    When   the add-ons' closure is worked out
    Then   it is what the add-ons reach, and the bundle's own packages stay out
    """
    closure = addon_licenses.addon_closure(_LOCK)

    assert [name for name, _version in closure] == [
        "annotated-types",
        "langchain-core",
        "numpy",
        "pydantic",
        "spacy",
        "typer",
    ]
    assert dict(closure)["spacy"] == "3.8.18"


def test_closure_is_empty_when_no_addon_is_locked() -> None:
    """
    Given  a lock without a single add-on package
    When   the closure is worked out
    Then   nothing is listed, instead of the whole lock
    """
    assert addon_licenses.addon_closure("numpy==2.5.5\n    # via teachers-teammate\n") == []


def test_an_or_expression_is_allowed_when_one_alternative_is() -> None:
    """
    Given  license expressions with alternatives, and one with a single license
    When   each is held against the deny list
    Then   only the ones with no usable alternative are refused
    """
    assert addon_licenses.denied_reason("LGPL-3.0-only OR GPL-2.0-only OR GPL-3.0-only") is None
    assert addon_licenses.denied_reason("GPL-3.0-only OR MIT") is None
    assert addon_licenses.denied_reason("MIT") is None
    assert addon_licenses.denied_reason("GPL-3.0-only OR AGPL-3.0") is not None


def test_an_and_expression_is_refused_when_any_part_is() -> None:
    """
    Given  a license expression whose parts all apply
    When   it is held against the deny list
    Then   one denied part is enough, since the package cannot be used without it
    """
    assert addon_licenses.denied_reason("MIT AND GPL-3.0-only") is not None
    assert addon_licenses.denied_reason("CC-BY-NC-4.0") is not None


def test_license_of_prefers_the_expression_then_the_classifier_then_the_text() -> None:
    """
    Given  PyPI's three ways of naming a license
    When   the license is read
    Then   the expression wins, then the classifier, then the first line of the free text
    """
    assert addon_licenses.license_of({"license_expression": "MIT"}) == "MIT"
    assert (
        addon_licenses.license_of(
            {"classifiers": ["License :: OSI Approved :: Apache Software License"]}
        )
        == "Apache Software License"
    )
    assert addon_licenses.license_of({"license": "BSD 3-Clause\n\nfull text"}) == "BSD 3-Clause"
    assert addon_licenses.license_of({}) == "unknown"


def test_collect_names_the_package_it_could_not_read() -> None:
    """
    Given  a PyPI that answers for one package and fails for another
    When   the licenses are collected
    Then   the failure names the package instead of a bare traceback
    """

    def fetch(name: str, version: str) -> dict:
        if name == "broken":
            raise OSError("no route to host")
        return {"license_expression": "MIT"}

    assert addon_licenses.collect([("spacy", "3.8.18")], fetch) == [("spacy", "3.8.18", "MIT")]
    with pytest.raises(SystemExit, match=r"broken 1\.0"):
        addon_licenses.collect([("broken", "1.0")], fetch)


def test_render_writes_a_header_and_one_row_per_package() -> None:
    """
    Given  two packages with their licenses
    When   the CSV is rendered
    Then   it has a header and one row each, with no trailing blank line
    """
    text = addon_licenses.render([("numpy", "2.5.5", "BSD-3-Clause"), ("spacy", "3.8.18", "MIT")])

    assert text == "Package,Version,License\nnumpy,2.5.5,BSD-3-Clause\nspacy,3.8.18,MIT\n"


def test_check_fails_when_the_committed_list_is_stale(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """
    Given  a lock, a PyPI answer and a committed list that does not match it
    When   the check runs, and again once the list is written
    Then   the first run fails and names the file, the second passes
    """
    lock = tmp_path / "requirements_addons_lock.txt"
    lock.write_text("spacy==3.8.18\n    # via teachers-teammate\n", encoding="utf-8")
    output = tmp_path / "addon_licenses.csv"
    monkeypatch.setattr(addon_licenses, "ROOT", tmp_path)
    monkeypatch.setattr(addon_licenses, "LOCK", lock)
    monkeypatch.setattr(addon_licenses, "OUTPUT", output)
    monkeypatch.setattr(addon_licenses, "_pypi_info", lambda _n, _v: {"license_expression": "MIT"})

    assert addon_licenses.main(["--check"]) == 1
    assert addon_licenses.main([]) == 0
    assert addon_licenses.main(["--check"]) == 0
    assert output.read_text(encoding="utf-8") == "Package,Version,License\nspacy,3.8.18,MIT\n"


def test_main_refuses_a_denied_license_and_writes_nothing(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    """
    Given  an add-on whose package is under a license we must not ship
    When   the list is written
    Then   the run fails, names the package and the reason, and leaves no file behind
    """
    lock = tmp_path / "requirements_addons_lock.txt"
    lock.write_text("spacy==3.8.18\n    # via teachers-teammate\n", encoding="utf-8")
    output = tmp_path / "addon_licenses.csv"
    monkeypatch.setattr(addon_licenses, "ROOT", tmp_path)
    monkeypatch.setattr(addon_licenses, "LOCK", lock)
    monkeypatch.setattr(addon_licenses, "OUTPUT", output)
    monkeypatch.setattr(
        addon_licenses, "_pypi_info", lambda _n, _v: {"license_expression": "AGPL-3.0"}
    )

    assert addon_licenses.main([]) == 1
    assert not output.exists()


def test_an_unknown_license_is_refused_until_it_is_listed(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """
    Given  a package whose PyPI metadata names no license
    When   the packages are held against the deny list
    Then   it is refused, unless a person listed it in UNKNOWN_ALLOWED with a reason
    """
    rows = [("mystery", "1.0", "unknown"), ("spacy", "3.8.18", "MIT")]

    problems = addon_licenses.denied(rows)
    assert len(problems) == 1
    assert problems[0].startswith("mystery 1.0 is unknown")

    monkeypatch.setitem(addon_licenses.UNKNOWN_ALLOWED, "mystery", "MIT text read in its sdist")
    assert addon_licenses.denied(rows) == []
